import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, GitHubIssuePayload, HandleResult } from './connector'
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      githubWebhookSecret: 'test-secret',
      linearApiKey: 'test-linear-key',
      linearTeamId: 'abc-123-team-uuid',
      linearLabelIdMap: { bug: 'label-uuid-for-bug', frontend: 'label-uuid-for-frontend' },
      linearAuthorIdMap: { 'alice-dev': 'user-uuid-for-alice-dev' },
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as GitHubIssuePayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.linearIssueId).toBe('issue-uuid-123')
    expect(result.linearIssueIdentifier).toBe('TRI-456')
    expect(result.linearIssueUrl).toBe('https://linear.app/tri/issue/TRI-456/')
  })
})

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    githubWebhookSecret: 'test-secret',
    linearApiKey: 'test-linear-key',
    linearTeamId: 'abc-123-team-uuid',
    linearLabelIdMap: { bug: 'label-uuid-for-bug', frontend: 'label-uuid-for-frontend' },
    linearAuthorIdMap: { 'alice-dev': 'user-uuid-for-alice-dev' },
  }

  it('maps fields correctly and calls Linear GraphQL endpoint', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://api.linear.app/graphql')
      expect(req.headers.get('authorization')).toBe('Bearer test-linear-key')
      const body = req.json as { query: string; variables: { input: Record<string, unknown> } }
      expect(body.query).toContain('mutation IssueCreate')
      expect(body.variables.input.title).toBe('Fix login button alignment')
      expect(body.variables.input.description).toBe('The login button is misaligned on mobile screens. Needs CSS fix.')
      expect(body.variables.input.teamId).toBe('abc-123-team-uuid')
      expect(body.variables.input.labelIds).toEqual(['label-uuid-for-bug', 'label-uuid-for-frontend'])
      expect(body.variables.input.authorId).toBe('user-uuid-for-alice-dev')
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    const result = await handle(SOURCE_EXAMPLE as unknown as GitHubIssuePayload, { ...baseConfig, fetch })
    expect(result.linearIssueId).toBe('issue-uuid-123')
    expect(calls.length).toBe(1)
  })

  it('uses defaultAuthorId when GitHub user not in map', async () => {
    const payload = { ...SOURCE_EXAMPLE, issue: { ...SOURCE_EXAMPLE.issue, user: { login: 'unknown-user' } } }
    const { fetch, calls } = fakeFetch((req) => {
      const body = req.json as { variables: { input: { authorId: string } } }
      expect(body.variables.input.authorId).toBe('default-user-uuid')
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    const config = { ...baseConfig, defaultAuthorId: 'default-user-uuid', fetch }
    const result = await handle(payload as unknown as GitHubIssuePayload, config)
    expect(result.linearIssueId).toBe('issue-uuid-123')
    expect(calls.length).toBe(1)
  })

  it('throws when action is not labeled', async () => {
    const payload = { ...SOURCE_EXAMPLE, action: 'unlabeled' }
    await expect(handle(payload as unknown as GitHubIssuePayload, baseConfig)).rejects.toThrow(
      'Unsupported action "unlabeled"'
    )
  })

  it('throws when bug label is missing', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      issue: { ...SOURCE_EXAMPLE.issue, labels: [{ name: 'frontend', color: 'fbca04' }] },
    }
    await expect(handle(payload as unknown as GitHubIssuePayload, baseConfig)).rejects.toThrow(
      'Issue does not have the "bug" label'
    )
  })

  it('throws when required field issue.title is missing', async () => {
    const payload = { ...SOURCE_EXAMPLE, issue: { ...SOURCE_EXAMPLE.issue, title: '' } }
    await expect(handle(payload as unknown as GitHubIssuePayload, baseConfig)).rejects.toThrow(
      'Missing required field: issue.title'
    )
  })

  it('throws when required field issue.user.login is missing', async () => {
    const payload = { ...SOURCE_EXAMPLE, issue: { ...SOURCE_EXAMPLE.issue, user: { login: '' } } }
    await expect(handle(payload as unknown as GitHubIssuePayload, baseConfig)).rejects.toThrow(
      'Missing required field: issue.user.login'
    )
  })

  it('throws when no labels can be mapped to Linear label IDs', async () => {
    const payload = {
      ...SOURCE_EXAMPLE,
      issue: { ...SOURCE_EXAMPLE.issue, labels: [{ name: 'unknown-label', color: '000000' }] },
    }
    await expect(handle(payload as unknown as GitHubIssuePayload, baseConfig)).rejects.toThrow(
      'None of the issue labels could be mapped to Linear label IDs'
    )
  })

  it('throws when author cannot be resolved and no defaultAuthorId', async () => {
    const payload = { ...SOURCE_EXAMPLE, issue: { ...SOURCE_EXAMPLE.issue, user: { login: 'ghost' } } }
    await expect(handle(payload as unknown as GitHubIssuePayload, baseConfig)).rejects.toThrow(
      'No Linear author ID found for GitHub user "ghost"'
    )
  })

  it('throws on non-2xx response from Linear API', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    await expect(handle(SOURCE_EXAMPLE as unknown as GitHubIssuePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Linear API error: 401 Unauthorized at https://api.linear.app/graphql'
    )
    expect(calls.length).toBe(1)
  })

  it('throws on GraphQL errors in response', async () => {
    const { fetch, calls } = fakeFetch(() =>
      jsonResponse({ errors: [{ message: 'Team not found' }] }, 200)
    )
    await expect(handle(SOURCE_EXAMPLE as unknown as GitHubIssuePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Linear GraphQL errors: Team not found'
    )
    expect(calls.length).toBe(1)
  })

  it('throws on unexpected response shape', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ data: { issueCreate: { success: false } } }, 200))
    await expect(handle(SOURCE_EXAMPLE as unknown as GitHubIssuePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Linear API returned unexpected response shape'
    )
    expect(calls.length).toBe(1)
  })
})

